import { useEffect, useState } from "react";
import { X, Loader2, UserRound } from "lucide-react";
import { getPersonalDetails } from "../services/auth";
import { formatPhoneNumber, formatPhoneDisplay } from "../services/phone";
import ProfilePhotoUploader from "./ProfilePhotoUploader";
import { createPlayerPersonalDetails, updatePlayerPersonalDetails } from "../services/player";
import {
  levelOptionsIncluding,
  normalizeProfileRating,
  resolveProfileLevel,
} from "../utils/profileRatings";
import { resolveSmsConsentGranted } from "../services/smsConsent";

import "./ProfileManager.css";

const emptyDetails = {
  id: null,
  full_name: "",
  email: "",
  phone: "",
  profile_picture: "",
  date_of_birth: "",
  usta_rating: "",
  uta_rating: "",
  calculated_ntrp: "",
  calculated_utr: "",
  self_rated_seed: "",
  seeded_at: null,
  matches_played: 0,
  about_me: "",
};

const NTRP_OPTIONS = ["2.5", "3.0", "3.5", "3.75", "4.0", "4.25", "4.5", "5.0"];

const positiveRating = (value) => {
  const numeric = Number(value);
  return Number.isFinite(numeric) && numeric > 0 ? numeric : null;
};

const ProfileManager = ({ isOpen, onClose, variant = "modal" }) => {
  const [details, setDetails] = useState(emptyDetails);
  const [phoneInput, setPhoneInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [imagePreview, setImagePreview] = useState("");
  const [successMessage, setSuccessMessage] = useState("");
  const [smsConsentGranted, setSmsConsentGranted] = useState(false);
  const [selfRatingDeclared, setSelfRatingDeclared] = useState(false);
  const accessToken = localStorage.getItem("authToken");
  const isPage = variant === "page";

  useEffect(() => {
    if (isPage) {
      fetchDetails();
      return () => {
        setDetails(emptyDetails);
        setPhoneInput("");
        setError("");
        setImagePreview("");
        setSuccessMessage("");
        setSmsConsentGranted(false);
        setSelfRatingDeclared(false);
      };
    }

    if (isOpen) {
      fetchDetails();
    } else {
      setDetails(emptyDetails);
      setPhoneInput("");
      setError("");
      setImagePreview("");
      setSuccessMessage("");
      setSmsConsentGranted(false);
      setSelfRatingDeclared(false);
    }
  }, [isOpen, isPage]);

  const fetchDetails = async ({ showLoader = true } = {}) => {
    try {
      if (showLoader) {
        setLoading(true);
      }
      const data = await getPersonalDetails();
      const normalizedDetails = {
        id: data?.id ?? null,
        full_name: data?.full_name || "",
        email: data?.email || "",
        phone: data?.phone ? String(data.phone).replace(/\D/g, "") : "",
        profile_picture: data?.profile_picture || "",
        date_of_birth: data?.date_of_birth
          ? data.date_of_birth.split("T")[0]
          : "",
        usta_rating: normalizeProfileRating(data?.usta_rating),
        uta_rating: normalizeProfileRating(data?.uta_rating),
        calculated_ntrp: normalizeProfileRating(data?.calculated_ntrp),
        calculated_utr: normalizeProfileRating(data?.calculated_utr),
        self_rated_seed: normalizeProfileRating(data?.self_rated_seed),
        seeded_at: data?.seeded_at || null,
        matches_played: Number(data?.matches_played || 0),
        about_me: data?.about_me || "",
      };
      setDetails(normalizedDetails);
      setPhoneInput(formatPhoneDisplay(data?.phone) || "");
      setSmsConsentGranted(resolveSmsConsentGranted(data));
      setImagePreview(normalizedDetails.profile_picture || "");
    } catch (err) {
      console.error(err);
      if (err?.status === 404) {
        setDetails(emptyDetails);
        setPhoneInput("");
        setImagePreview("");
        setError("");
      } else {
        setError("Failed to load profile details. Please try again.");
      }
    } finally {
      if (showLoader) {
        setLoading(false);
      }
    }
  };

  const handlePhoneChange = (value) => {
    const formatted = formatPhoneNumber(value);
    const digits = formatted.replace(/\D/g, "");
    setPhoneInput(formatted);
    setDetails((prev) => ({ ...prev, phone: digits }));
  };

  const handleUpdate = async (e) => {
    e.preventDefault();
    setError("");
    setSuccessMessage("");
    setSaving(true);
    if (!accessToken) {
      setSaving(false);
      setError("Please sign in again to update your profile.");
      return;
    }
    try {
      const parseRating = (value) => {
        if (value === "" || value === null || value === undefined) {
          return undefined;
        }
        const numeric = Number(value);
        return Number.isFinite(numeric) ? numeric : undefined;
      };

      const sanitizedPhone = String(details.phone || "").replace(/\D/g, "");
      if (sanitizedPhone && !smsConsentGranted) {
        setError("Please agree to receive SMS messages before saving your mobile number.");
        setSaving(false);
        return;
      }
      if (canEditRating && details.usta_rating && !selfRatingDeclared) {
        setError("Please declare that your self-rating is accurate before saving.");
        setSaving(false);
        return;
      }
      const aboutMe = details.about_me?.trim();
      const payload = {
        player: accessToken,
        date_of_birth: details.date_of_birth || null,
        usta_rating: canEditRating ? parseRating(details.usta_rating) : undefined,
        uta_rating: parseRating(details.uta_rating),
        fullName: details.full_name?.trim() || null,
        mobile: sanitizedPhone ? sanitizedPhone : null,
        about_me: aboutMe || null,
        smsConsentGranted,
        smsConsentMethod: "player_profile",
      };

      const response = details.id
        ? await updatePlayerPersonalDetails({
            ...payload,
            id: details.id,
          })
        : await createPlayerPersonalDetails(payload);

      if (response?.id && response.id !== details.id) {
        setDetails((prev) => ({ ...prev, id: response.id }));
      }
      if (isPage) {
        setSuccessMessage("Profile updated successfully.");
        fetchDetails({ showLoader: false });
      } else {
        onClose?.();
      }
    } catch (err) {
      console.error(err);
      setError(
        err?.response?.data?.message ||
          err?.message ||
          "We couldn't save your profile. Please try again."
      );
    } finally {
      setSaving(false);
    }
  };

  if (!isPage && !isOpen) return null;

  const HeaderContent = (
    <div className="profile-manager__header">
      <div className="profile-manager__title-group">
        <div className="profile-manager__avatar">
          <UserRound className="profile-manager__avatar-icon" aria-hidden="true" />
        </div>
        <div>
          <h2 className="profile-manager__title">Player profile</h2>
          <p className="profile-manager__subtitle">Keep your personal information up to date</p>
        </div>
      </div>
      {!isPage && (
        <button
          onClick={onClose}
          type="button"
          className="profile-manager__close"
          aria-label="Close profile manager"
        >
          <X aria-hidden="true" />
        </button>
      )}
    </div>
  );

  const declaredRating = positiveRating(details.usta_rating);
  const matchRating = positiveRating(details.calculated_ntrp);
  const hasMatchRating = Number(details.matches_played || 0) > 0 && matchRating !== null;
  const canEditRating = !details.seeded_at && !hasMatchRating;
  // Once locked, show whatever level the player has, including the rating
  // quiz's estimate, which is saved as self_rated_seed rather than usta_rating.
  const shownLevel = canEditRating
    ? { value: details.usta_rating, source: null }
    : resolveProfileLevel(details);
  const ratingValue = shownLevel.value;
  const ratingOptions = levelOptionsIncluding(NTRP_OPTIONS, ratingValue);
  const ratingHelper = canEditRating
    ? "Choose once. After saving, only an admin can edit this."
    : hasMatchRating
      ? "Your level is now match-derived. Ask support if this needs correction."
      : declaredRating !== null
        ? "Saved. Only an admin can edit this now."
        : shownLevel.source === "quiz"
          ? "Estimated by the rating quiz. Only an admin can edit this now."
          : "Only an admin can edit this now.";

  const FormContent = (
    <form onSubmit={handleUpdate} className="profile-manager__form">
      {loading ? (
        <div className="profile-manager__loading">
          <Loader2 className="profile-manager__spinner" aria-hidden="true" />
        </div>
      ) : (
        <>
          <div className="profile-manager__field profile-manager__field--photo">
            <label className="profile-manager__label" htmlFor="profile-photo">
              Profile photo
            </label>
            <div className="profile-manager__photo-row">
              <div className="profile-manager__photo-preview" aria-hidden={!imagePreview}>
                <div className="profile-manager__photo-frame">
                  {imagePreview ? (
                    <img src={imagePreview} alt="Profile preview" />
                  ) : (
                    <UserRound className="profile-manager__photo-fallback" aria-hidden="true" />
                  )}
                </div>
              </div>
              <div className="profile-manager__photo-actions">
                <ProfilePhotoUploader
                  accessToken={accessToken}
                  onUploaded={() => fetchDetails({ showLoader: false })}
                  className="profile-manager__upload"
                  disabledLabel="Uploading…"
                  label="Upload from device"
                  errorClassName="profile-manager__upload-error"
                />
                <p className="profile-manager__helper">JPG or PNG, up to 5MB. We&apos;ll resize it for your profile.</p>
              </div>
            </div>
          </div>

          <h3 className="profile-manager__subhead">Contact and identity</h3>

          <div className="profile-manager__field">
            <label className="profile-manager__label" htmlFor="profile-full-name">
              Full name
            </label>
            <input
              id="profile-full-name"
              className="profile-manager__input"
              type="text"
              placeholder="Jane Doe"
              value={details.full_name}
              onChange={(e) =>
                setDetails((prev) => ({
                  ...prev,
                  full_name: e.target.value,
                }))
              }
              autoFocus
            />
          </div>

          <div className="profile-manager__field">
            <div className="profile-manager__label-row">
              <label className="profile-manager__label" htmlFor="profile-email">
                Email
              </label>
              <span className="profile-manager__tag">Managed</span>
            </div>
            <input
              id="profile-email"
              className="profile-manager__input profile-manager__input--readonly"
              type="email"
              value={details.email}
              readOnly
              disabled
            />
            <p className="profile-manager__helper">Email is managed by your account sign-in settings.</p>
          </div>

          <div className="profile-manager__field">
            <label className="profile-manager__label" htmlFor="profile-mobile">
              Mobile number
            </label>
            <input
              id="profile-mobile"
              className="profile-manager__input"
              type="tel"
              placeholder="(555) 123-4567"
              value={phoneInput}
              onChange={(e) => handlePhoneChange(e.target.value)}
              maxLength={14}
              inputMode="tel"
            />
            <p className="profile-manager__helper">We&apos;ll use this number to share match reminders.</p>
          </div>

          <div className="profile-manager__field">
            <label className="profile-manager__label" htmlFor="profile-dob">
              Date of birth
            </label>
            <input
              id="profile-dob"
              className="profile-manager__input"
              type="date"
              value={details.date_of_birth}
              onChange={(e) =>
                setDetails((prev) => ({
                  ...prev,
                  date_of_birth: e.target.value,
                }))
              }
            />
          </div>

          <h3 className="profile-manager__subhead">Tennis level</h3>

          <div className="profile-manager__field">
            <label className="profile-manager__label" htmlFor="profile-usta-rating">
              Self-declared NTRP
            </label>
            <select
              id="profile-usta-rating"
              className="profile-manager__input"
              value={ratingValue}
              disabled={!canEditRating}
              onChange={(e) =>
                setDetails((prev) => ({
                  ...prev,
                  usta_rating: e.target.value,
                }))
              }
            >
              <option value="">Select your level</option>
              {ratingOptions.map((rating) => (
                <option key={rating} value={rating}>
                  {rating}
                </option>
              ))}
            </select>
            <p className="profile-manager__helper">{ratingHelper}</p>
          </div>

          {canEditRating && details.usta_rating ? (
            <label className="profile-manager__field profile-manager__field--declaration">
              <span className="profile-manager__label">Self-rating declaration</span>
              <span className="profile-manager__helper">
                <input
                  id="profile-self-rating-declaration"
                  type="checkbox"
                  checked={selfRatingDeclared}
                  onChange={(event) => setSelfRatingDeclared(event.target.checked)}
                  required
                />{" "}
                I declare that my self-rating above is accurate and I will play at this level.
              </span>
            </label>
          ) : null}

          {details.phone ? (
            <label className="profile-manager__field" htmlFor="profile-sms-consent">
              <span className="profile-manager__label">SMS consent</span>
              <span className="profile-manager__helper">
                <input
                  id="profile-sms-consent"
                  type="checkbox"
                  checked={smsConsentGranted}
                  onChange={(event) => setSmsConsentGranted(event.target.checked)}
                  required
                />{" "}
                I agree to receive SMS messages from The Tennis Plan. Msg &amp; data rates may apply. Reply STOP to opt out.
              </span>
            </label>
          ) : null}
        </>
      )}

      {error && <div className="profile-manager__alert profile-manager__alert--error">{error}</div>}

      <div className="profile-manager__actions">
        {!isPage && (
          <button type="button" onClick={onClose} className="profile-manager__secondary">
            Cancel
          </button>
        )}
        <button type="submit" disabled={saving || loading} className="profile-manager__primary">
          {saving ? (
            <>
              <Loader2 className="profile-manager__primary-spinner" aria-hidden="true" />
              Saving
            </>
          ) : (
            "Save"
          )}
        </button>
      </div>
    </form>
  );

  if (isPage) {
    return (
      <div className="profile-manager profile-manager--page">
        {successMessage && <div className="profile-manager__alert profile-manager__alert--success">{successMessage}</div>}
        <div className="profile-manager__card">
          {HeaderContent}
          {FormContent}
        </div>
      </div>
    );
  }

  return (
    <div className="profile-manager__modal" role="dialog" aria-modal="true">
      <div className="profile-manager__modal-card">
        {HeaderContent}
        {FormContent}
      </div>
    </div>
  );
};

export default ProfileManager;
